-- Source: MotherDuck thyroid_canonical_publication_v1_0.manuscript_workspace.ete_manuscript_analytic_v6
-- Captured: 2026-05-06 for THY-19 BQ migration

CREATE VIEW manuscript_workspace.ete_manuscript_analytic_v6 AS WITH inline_pt AS (SELECT research_id, ete_grade_resolved AS inline_grade, resolution_set AS inline_set, evidence_quote AS inline_evidence, resolution_source AS inline_source FROM main.canonical_ete_inline_adjudication_v1 WHERE (tumor_ordinal IS NULL) QUALIFY (row_number() OVER (PARTITION BY research_id ORDER BY CASE  WHEN ((resolution_set = 'queue_straggler')) THEN (1) WHEN ((resolution_set = 'pm_disagreement_gross_vs_micro')) THEN (2) WHEN ((resolution_set = 'queue_boolean_string_upstream_bug')) THEN (3) ELSE 4 END) = 1)), inline_evt AS (SELECT research_id, tumor_ordinal, ete_grade_resolved AS inline_evt_grade, evidence_quote AS inline_evt_evidence, resolution_set AS inline_evt_set FROM main.canonical_ete_inline_adjudication_v1 WHERE (tumor_ordinal IS NOT NULL))SELECT v4.*, ipt.inline_grade, ipt.inline_set, ipt.inline_evidence, ipt.inline_source, ievt.inline_evt_grade, ievt.inline_evt_evidence, ievt.inline_evt_set, CASE  WHEN ((ievt.inline_evt_grade IN ('gross', 'microscopic', 'none'))) THEN (ievt.inline_evt_grade) WHEN ((ievt.inline_evt_grade = 'unable_to_determine')) THEN ('unable_to_determine') WHEN ((ipt.inline_set = 'pm_disagreement_gross_vs_micro')) THEN (ipt.inline_grade) WHEN (((v4.ete_grade_final_v4 IS NULL) AND (ipt.inline_grade IN ('gross', 'microscopic', 'none')))) THEN (ipt.inline_grade) WHEN (((v4.ete_grade_final_v4 IS NULL) AND (ipt.inline_grade = 'unable_to_determine'))) THEN ('unable_to_determine') ELSE v4.ete_grade_final_v4 END AS ete_grade_final_v6, CASE  WHEN ((ievt.inline_evt_grade IS NOT NULL)) THEN ('inline_adjudication_event') WHEN ((ipt.inline_set = 'pm_disagreement_gross_vs_micro')) THEN ('inline_adjudication_pm_disagreement') WHEN (((v4.ete_grade_final_v4 IS NULL) AND (ipt.inline_grade IS NOT NULL))) THEN (CASE  WHEN ((ipt.inline_set = 'queue_straggler')) THEN ('inline_adjudication_queue') WHEN ((ipt.inline_set ~~ 'queue_microscopic_no_invasion_signal%')) THEN ('inline_admin_accept_script_390') WHEN ((ipt.inline_set = 'queue_boolean_string_upstream_bug')) THEN ('inline_admin_boolean_bug_fix') ELSE 'inline_adjudication_other' END) ELSE v4.ete_grade_source_v4 END AS ete_grade_source_v6 FROM manuscript_workspace.ete_manuscript_analytic_v4 AS v4 LEFT JOIN inline_pt AS ipt ON ((ipt.research_id = CAST(v4.research_id AS VARCHAR))) LEFT JOIN inline_evt AS ievt ON (((ievt.research_id = CAST(v4.research_id AS VARCHAR)) AND (ievt.tumor_ordinal = v4.tumor_ordinal)));
